body {
      font-family: Arial, sans-serif;
      background: #b1f8af;
      padding: 10px;
  }

  .card {
      max-width: 360px;
      margin: 20px auto;
      padding: 18px;
      background: rgb(199, 240, 193);
      border: 1px solid #81e6b6;
      border-radius: 12px;
      box-shadow: 0 4px 12px #0f172a18;
  }

  .card h2 {
      color: #43da57;
      margin-top: 0;
  }

  .card a {
      color: #063b04;
  }
